{
  "findings": [
    {
      "check_id": "CKV_GCP_38",
      "title": "Instance metadata serial port enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance has serial port access enabled, potentially allowing unauthorized access."
    },
    {
      "check_id": "CKV_GCP_32",
      "title": "Instance service account scope is too permissive",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "HIGH",
      "explanation": "The 'cloud-platform' scope is too broad and should be restricted to necessary permissions."
    },
    {
      "check_id": "CKV_GCP_40",
      "title": "Instance has public IP address",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "CRITICAL",
      "explanation": "The instance has a public IP address due to the presence of 'access_config {}', making it potentially accessible from the internet."
    }
  ],
  "patched_code": "resource "google_compute_instance" "backup_orchestration_engine" {
  name         = "enterprise-disaster-recovery-orchestration-platform-compute-orchestration"
  machine_type = "e2-medium"
  zone         = "${var.primary_region}-a"
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-11"
      size  = 50
    }
  }
  network_interface {
    network    = google_compute_network.dr_vpc.id
    subnetwork = google_compute_subnetwork.management_subnet.id
  }
  service_account {
    email  = "123456789-compute@developer.gserviceaccount.com"
    scopes = ["https://www.googleapis.com/auth/compute.readonly", "https://www.googleapis.com/auth/logging.write", "https://www.googleapis.com/auth/monitoring.write"]
  }
  metadata = {
    serial-port-enable = false
    startup-script     = file("${path.module}/scripts/orchestration-startup.sh")
  }
  tags = ["dr-internal", "orchestration-engine"]
  depends_on = [
    google_storage_bucket.primary_backup_storage,
    google_sql_database_instance.recovery_database
  ]
}",
  "fix_summary": "Disabled serial port access, removed public IP address, and restricted service account scopes to necessary permissions."
}
